/**
 * What the eye does with a planet's light, after the scene is drawn — CODE-SPLIT.
 *
 * A REGISTERED CHUNK MANIFEST MODULE (MANIFEST_MODULES and ALLOWLIST in
 * tooling/check-shader-imports.mjs): the import site of the post-processes
 * and the small render targets below, loaded only by dynamic `import()` from
 * the planet view, for a world whose eye adapts or sees the sun's beams.
 *
 * The eye adapts (eye.ts has the arithmetic). After each frame, two small
 * passes measure it: a 32 by 18 grid of cells, each the mean logarithm of 16
 * samples' brightness, then one pixel that weighs the grid toward the middle,
 * eases the eye's level toward it from the level it held the frame before,
 * and works out the exposure. The two one-pixel targets take turns as before
 * and after. Nothing is read back to the processor; the next frame's view
 * reads the exposure from the pixel.
 *
 * The sun's beams are a blur toward the sun's place on the screen, at a
 * quarter of the view's size: the first pass gathers what is bright about the
 * sun along the way (the sky and clouds; ground and trees, darker, give
 * nothing, so their gaps make the shafts), a second blurs along the same line
 * over the first's gaps, and the view adds them before its exposure. They
 * fade as the sun goes off the screen or down.
 *
 * Passes after the scene, in order: the beams' two (when drawn), then the
 * view's own, which adds the beams and applies the exposure. A pass's own
 * texture is what it is drawn from, so the scene is drawn into the first of
 * them, and the view's pass reads it from there.
 */
import { PostProcess } from '@babylonjs/core/PostProcesses/postProcess';
import { EffectRenderer, EffectWrapper } from '@babylonjs/core/Materials/effectRenderer';
import { RenderTargetTexture } from '@babylonjs/core/Materials/Textures/renderTargetTexture';
import { ShaderLanguage } from '@babylonjs/core/Materials/shaderLanguage';
import { ShaderStore } from '@babylonjs/core/Engines/shaderStore';
import { Constants } from '@babylonjs/core/Engines/constants';
import type { Camera } from '@babylonjs/core/Cameras/camera';
import type { Effect } from '@babylonjs/core/Materials/effect';
import type { Observer } from '@babylonjs/core/Misc/observable';
import type { Scene } from '@babylonjs/core/scene';
import type { EyeFrame, EyeHandle } from './planetView';
import { EYE, sunbeamsByHeight, sunOnScreen } from './eye';

/** The beams' passes, as a share of the view's size. */
const BEAMS_SCALE = 0.25;
/** Samples along the way to the sun in the beams' first pass, and across one of its gaps in the second. */
const BEAMS_SAMPLES = 32;
const BLUR_SAMPLES = 8;
/** How much less each sample further from the pixel, toward the sun, counts. */
const BEAMS_DECAY = 0.965;
/** The brightness above which the view gives beams, and how far about the sun (in screen heights, as an exponent's scale) it gives them from. */
const BEAMS_THRESHOLD = 0.62;
const BEAMS_FALLOFF = 8.0;
/**
 * The beams as the view adds them, at the world's full strength. They are the light the air scatters toward
 * the eye, seen against what is darker behind it: over the bright sky about the sun they add almost nothing,
 * so the sun's glow does not swell, and over ground, trunks and leaves they show as shafts.
 */
const BEAMS_GAIN = 1.1;
/** The brightness of the view below which the beams show whole, and above which they are gone. */
const BEAMS_DARK: [number, number] = [0.25, 0.85];
/** The measuring grid. */
const METER_W = 32;
const METER_H = 18;
/** How much the middle of the view counts in the measure over its edges. */
const METER_CENTRE = 2.5;

const f = (x: number) => (Number.isInteger(x) ? `${x}.0` : String(x));

// ---- GLSL (WebGL) ----

const BEAMS_GLSL = `
varying vec2 vUV;
uniform sampler2D textureSampler;
uniform vec2 sunUv;
uniform float strength;
uniform float aspect;
vec3 bright(vec2 uv) {
  vec3 c = texture2D(textureSampler, uv).rgb;
  float y = dot(c, vec3(0.2126, 0.7152, 0.0722));
  vec2 d = (uv - sunUv) * vec2(aspect, 1.0);
  float inside = step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
  return c * smoothstep(${f(BEAMS_THRESHOLD)}, ${f(BEAMS_THRESHOLD + 0.25)}, y) * exp(-dot(d, d) * ${f(BEAMS_FALLOFF)}) * inside;
}
void main(void) {
  if (strength <= 0.0) { gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0); return; }
  vec2 stepUv = (sunUv - vUV) / ${f(BEAMS_SAMPLES)};
  float jitter = fract(52.9829189 * fract(dot(gl_FragCoord.xy, vec2(0.06711056, 0.00583715))));
  vec2 uv = vUV + stepUv * jitter;
  vec3 sum = vec3(0.0);
  float w = 1.0;
  float total = 0.0;
  for (int i = 0; i < ${BEAMS_SAMPLES}; i++) {
    sum += bright(uv) * w;
    total += w;
    w *= ${f(BEAMS_DECAY)};
    uv += stepUv;
  }
  gl_FragColor = vec4(sum / total * strength, 1.0);
}`;

const BLUR_GLSL = `
varying vec2 vUV;
uniform sampler2D textureSampler;
uniform vec2 sunUv;
void main(void) {
  vec2 stepUv = (sunUv - vUV) / ${f(BEAMS_SAMPLES * BLUR_SAMPLES)};
  vec3 sum = vec3(0.0);
  for (int i = 0; i < ${BLUR_SAMPLES}; i++) sum += texture2D(textureSampler, vUV + stepUv * (float(i) - ${f(BLUR_SAMPLES / 2 - 0.5)})).rgb;
  gl_FragColor = vec4(sum / ${f(BLUR_SAMPLES)}, 1.0);
}`;

const VIEW_GLSL = `
varying vec2 vUV;
uniform sampler2D textureSampler;
uniform sampler2D eyeSampler;
#ifdef SUNBEAMS
uniform sampler2D sceneSampler;
#endif
uniform float exposure;
uniform float adapt;
void main(void) {
#ifdef SUNBEAMS
  vec3 c = texture2D(sceneSampler, vUV).rgb;
  float behind = 1.0 - smoothstep(${f(BEAMS_DARK[0])}, ${f(BEAMS_DARK[1])}, dot(c, vec3(0.2126, 0.7152, 0.0722)));
  c += texture2D(textureSampler, vUV).rgb * ${f(BEAMS_GAIN)} * behind;
#else
  vec3 c = texture2D(textureSampler, vUV).rgb;
#endif
  float e = mix(exposure, texture2D(eyeSampler, vec2(0.5)).g, adapt);
  gl_FragColor = vec4(vec3(1.0) - pow(vec3(1.0) - clamp(c, 0.0, 1.0), vec3(e)), 1.0);
}`;

const METER_GLSL = `
varying vec2 vUV;
uniform sampler2D textureSampler;
void main(void) {
  vec2 cell = vec2(${f(1 / METER_W)}, ${f(1 / METER_H)});
  vec2 corner = floor(vUV / cell) * cell;
  float s = 0.0;
  for (int j = 0; j < 4; j++) for (int i = 0; i < 4; i++) {
    vec3 c = texture2D(textureSampler, corner + cell * (vec2(float(i), float(j)) + 0.5) / 4.0).rgb;
    s += log(max(dot(c, vec3(0.2126, 0.7152, 0.0722)), 0.0001));
  }
  gl_FragColor = vec4(s / 16.0, 0.0, 0.0, 1.0);
}`;

const ADAPT_GLSL = `
varying vec2 vUV;
uniform sampler2D meterSampler;
uniform sampler2D previousSampler;
uniform float dt;
uniform float speed;
uniform float lo;
uniform float hi;
uniform float reset;
void main(void) {
  float s = 0.0;
  float total = 0.0;
  for (int j = 0; j < ${METER_H}; j++) for (int i = 0; i < ${METER_W}; i++) {
    vec2 uv = (vec2(float(i), float(j)) + 0.5) / vec2(${f(METER_W)}, ${f(METER_H)});
    vec2 d = uv - 0.5;
    float w = exp(-dot(d, d) * ${f(METER_CENTRE)});
    s += texture2D(meterSampler, uv).r * w;
    total += w;
  }
  float measured = s / total;
  float before = texture2D(previousSampler, vec2(0.5)).r;
  float tau = measured > before ? ${f(EYE.tauBrighten)} : ${f(EYE.tauDarken)};
  float level = reset > 0.5 ? measured : measured + (before - measured) * exp(-dt * speed / tau);
  float e = clamp(pow(${f(EYE.key)} / exp(level), ${f(EYE.response)}), lo, hi);
  gl_FragColor = vec4(level, e, 0.0, 1.0);
}`;

// ---- WGSL (WebGPU): the same passes, in Babylon's WGSL post-process dialect. ----

const BEAMS_WGSL = `
varying vUV: vec2f;
var textureSamplerSampler: sampler;
var textureSampler: texture_2d<f32>;
uniform sunUv: vec2f;
uniform strength: f32;
uniform aspect: f32;
fn bright(uv: vec2f) -> vec3f {
  let c = textureSampleLevel(textureSampler, textureSamplerSampler, uv, 0.0).rgb;
  let y = dot(c, vec3f(0.2126, 0.7152, 0.0722));
  let d = (uv - uniforms.sunUv) * vec2f(uniforms.aspect, 1.0);
  let inside = step(0.0, uv.x) * step(uv.x, 1.0) * step(0.0, uv.y) * step(uv.y, 1.0);
  return c * smoothstep(${f(BEAMS_THRESHOLD)}, ${f(BEAMS_THRESHOLD + 0.25)}, y) * exp(-dot(d, d) * ${f(BEAMS_FALLOFF)}) * inside;
}
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  if (uniforms.strength <= 0.0) {
    fragmentOutputs.color = vec4f(0.0, 0.0, 0.0, 1.0);
    return fragmentOutputs;
  }
  let stepUv = (uniforms.sunUv - input.vUV) / ${f(BEAMS_SAMPLES)};
  let jitter = fract(52.9829189 * fract(dot(fragmentInputs.position.xy, vec2f(0.06711056, 0.00583715))));
  var uv = input.vUV + stepUv * jitter;
  var sum = vec3f(0.0);
  var w = 1.0;
  var total = 0.0;
  for (var i = 0; i < ${BEAMS_SAMPLES}; i++) {
    sum += bright(uv) * w;
    total += w;
    w *= ${f(BEAMS_DECAY)};
    uv += stepUv;
  }
  fragmentOutputs.color = vec4f(sum / total * uniforms.strength, 1.0);
}`;

const BLUR_WGSL = `
varying vUV: vec2f;
var textureSamplerSampler: sampler;
var textureSampler: texture_2d<f32>;
uniform sunUv: vec2f;
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  let stepUv = (uniforms.sunUv - input.vUV) / ${f(BEAMS_SAMPLES * BLUR_SAMPLES)};
  var sum = vec3f(0.0);
  for (var i = 0; i < ${BLUR_SAMPLES}; i++) {
    sum += textureSampleLevel(textureSampler, textureSamplerSampler, input.vUV + stepUv * (f32(i) - ${f(BLUR_SAMPLES / 2 - 0.5)}), 0.0).rgb;
  }
  fragmentOutputs.color = vec4f(sum / ${f(BLUR_SAMPLES)}, 1.0);
}`;

const VIEW_WGSL = `
varying vUV: vec2f;
var textureSamplerSampler: sampler;
var textureSampler: texture_2d<f32>;
var eyeSamplerSampler: sampler;
var eyeSampler: texture_2d<f32>;
#ifdef SUNBEAMS
var sceneSamplerSampler: sampler;
var sceneSampler: texture_2d<f32>;
#endif
uniform exposure: f32;
uniform adapt: f32;
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
#ifdef SUNBEAMS
  let seen = textureSample(sceneSampler, sceneSamplerSampler, input.vUV).rgb;
  let behind = 1.0 - smoothstep(${f(BEAMS_DARK[0])}, ${f(BEAMS_DARK[1])}, dot(seen, vec3f(0.2126, 0.7152, 0.0722)));
  let c = seen + textureSample(textureSampler, textureSamplerSampler, input.vUV).rgb * ${f(BEAMS_GAIN)} * behind;
#else
  let c = textureSample(textureSampler, textureSamplerSampler, input.vUV).rgb;
#endif
  let e = mix(uniforms.exposure, textureSample(eyeSampler, eyeSamplerSampler, vec2f(0.5)).g, uniforms.adapt);
  fragmentOutputs.color = vec4f(vec3f(1.0) - pow(vec3f(1.0) - clamp(c, vec3f(0.0), vec3f(1.0)), vec3f(e)), 1.0);
}`;

const METER_WGSL = `
varying vUV: vec2f;
var textureSamplerSampler: sampler;
var textureSampler: texture_2d<f32>;
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  let cell = vec2f(${f(1 / METER_W)}, ${f(1 / METER_H)});
  let corner = floor(input.vUV / cell) * cell;
  var s = 0.0;
  for (var j = 0; j < 4; j++) {
    for (var i = 0; i < 4; i++) {
      let c = textureSampleLevel(textureSampler, textureSamplerSampler, corner + cell * (vec2f(f32(i), f32(j)) + 0.5) / 4.0, 0.0).rgb;
      s += log(max(dot(c, vec3f(0.2126, 0.7152, 0.0722)), 0.0001));
    }
  }
  fragmentOutputs.color = vec4f(s / 16.0, 0.0, 0.0, 1.0);
}`;

const ADAPT_WGSL = `
varying vUV: vec2f;
var meterSamplerSampler: sampler;
var meterSampler: texture_2d<f32>;
var previousSamplerSampler: sampler;
var previousSampler: texture_2d<f32>;
uniform dt: f32;
uniform speed: f32;
uniform lo: f32;
uniform hi: f32;
uniform reset: f32;
@fragment
fn main(input: FragmentInputs) -> FragmentOutputs {
  var s = 0.0;
  var total = 0.0;
  for (var j = 0; j < ${METER_H}; j++) {
    for (var i = 0; i < ${METER_W}; i++) {
      let uv = (vec2f(f32(i), f32(j)) + 0.5) / vec2f(${f(METER_W)}, ${f(METER_H)});
      let d = uv - 0.5;
      let w = exp(-dot(d, d) * ${f(METER_CENTRE)});
      s += textureSampleLevel(meterSampler, meterSamplerSampler, uv, 0.0).r * w;
      total += w;
    }
  }
  let measured = s / total;
  let before = textureSampleLevel(previousSampler, previousSamplerSampler, vec2f(0.5), 0.0).r;
  var tau = ${f(EYE.tauDarken)};
  if (measured > before) { tau = ${f(EYE.tauBrighten)}; }
  var level = measured + (before - measured) * exp(-uniforms.dt * uniforms.speed / tau);
  if (uniforms.reset > 0.5) { level = measured; }
  let e = clamp(pow(${f(EYE.key)} / exp(level), ${f(EYE.response)}), uniforms.lo, uniforms.hi);
  fragmentOutputs.color = vec4f(level, e, 0.0, 1.0);
}`;

const SOURCES = {
  planetSunbeams: [BEAMS_GLSL, BEAMS_WGSL],
  planetSunbeamsBlur: [BLUR_GLSL, BLUR_WGSL],
  planetEye: [VIEW_GLSL, VIEW_WGSL],
  planetEyeMeter: [METER_GLSL, METER_WGSL],
  planetEyeAdapt: [ADAPT_GLSL, ADAPT_WGSL],
} as const;

/** The passes' sources for the engine: WGSL on WebGPU, GLSL otherwise. */
export function eyeShaderLanguage(engineKind?: string): ShaderLanguage {
  return engineKind === 'webgpu' ? ShaderLanguage.WGSL : ShaderLanguage.GLSL;
}

export function createEye(scene: Scene, camera: Camera, opts: { engineKind?: string; sunbeams: boolean }): EyeHandle {
  const engine = scene.getEngine();
  const language = eyeShaderLanguage(opts.engineKind);
  const wgsl = language === ShaderLanguage.WGSL;
  for (const [name, [glsl, wgslSource]] of Object.entries(SOURCES)) {
    const store = wgsl ? ShaderStore.ShadersStoreWGSL : ShaderStore.ShadersStore;
    store[`${name}PixelShader`] ??= wgsl ? wgslSource : glsl;
  }

  // The eye's measure: the grid, and the two one-pixel levels that take turns as before and after.
  const target = (name: string, w: number, h: number) =>
    new RenderTargetTexture(name, { width: w, height: h }, scene, false, true, Constants.TEXTURETYPE_HALF_FLOAT, false, Constants.TEXTURE_NEAREST_SAMPLINGMODE, false, false, false, Constants.TEXTUREFORMAT_RGBA);
  const meterTarget = target('planetEyeMeter', METER_W, METER_H);
  const levels = [target('planetEyeLevelA', 1, 1), target('planetEyeLevelB', 1, 1)];
  let latest = 0;
  const renderer = new EffectRenderer(engine);
  const meter = new EffectWrapper({ engine, name: 'planetEyeMeter', fragmentShader: 'planetEyeMeter', useShaderStore: true, samplerNames: ['textureSampler'], shaderLanguage: language });
  const adaptPass = new EffectWrapper({ engine, name: 'planetEyeAdapt', fragmentShader: 'planetEyeAdapt', useShaderStore: true, uniformNames: ['dt', 'speed', 'lo', 'hi', 'reset'], samplerNames: ['meterSampler', 'previousSampler'], shaderLanguage: language });

  let passes: { beams?: PostProcess; blur?: PostProcess; view: PostProcess } | null = null;
  let drawn = { beams: false, view: false };
  let now: EyeFrame | null = null;
  let sunUv: [number, number] = [0.5, 0.5];
  let beamsStrength = 0;
  let reset = true;

  const removePasses = () => {
    if (!passes) return;
    passes.beams?.dispose(camera);
    passes.blur?.dispose(camera);
    passes.view.dispose(camera);
    passes = null;
  };
  const makePasses = (beams: boolean) => {
    const common = { camera, engine, samplingMode: Constants.TEXTURE_BILINEAR_SAMPLINGMODE, shaderLanguage: language };
    const made: { beams?: PostProcess; blur?: PostProcess; view: PostProcess } = {} as never;
    if (beams) {
      // The scene is drawn into the first pass's texture, at the view's size; the beams are drawn into the blur's, at a quarter of it.
      made.beams = new PostProcess('planetSunbeams', 'planetSunbeams', { ...common, uniforms: ['sunUv', 'strength', 'aspect'], size: 1 });
      made.beams.onApply = (effect: Effect) => {
        effect.setFloat2('sunUv', sunUv[0], sunUv[1]);
        effect.setFloat('strength', beamsStrength);
        effect.setFloat('aspect', engine.getRenderWidth() / Math.max(1, engine.getRenderHeight()));
      };
      made.blur = new PostProcess('planetSunbeamsBlur', 'planetSunbeamsBlur', { ...common, uniforms: ['sunUv'], size: BEAMS_SCALE, textureType: Constants.TEXTURETYPE_HALF_FLOAT });
      made.blur.onApply = (effect: Effect) => effect.setFloat2('sunUv', sunUv[0], sunUv[1]);
    }
    made.view = new PostProcess('planetEye', 'planetEye', {
      ...common,
      uniforms: ['exposure', 'adapt'],
      samplers: beams ? ['eyeSampler', 'sceneSampler'] : ['eyeSampler'],
      size: beams ? BEAMS_SCALE : 1,
      ...(beams ? { textureType: Constants.TEXTURETYPE_HALF_FLOAT, defines: '#define SUNBEAMS' } : {}),
    });
    made.view.onApply = (effect: Effect) => {
      const e = now?.exposure;
      effect.setFloat('exposure', e?.mode === 'fixed' ? e.value : 1);
      effect.setFloat('adapt', e?.mode === 'auto' && !reset ? 1 : 0);
      effect.setTexture('eyeSampler', levels[latest]!);
      if (made.beams) effect.setTextureFromPostProcess('sceneSampler', made.beams);
    };
    passes = made;
  };

  // After each frame, the eye measures what it saw: from the scene as drawn into the first pass, into the next level.
  meter.onApplyObservable.add(() => {
    const first = passes?.beams ?? passes?.view;
    if (first) meter.effect.setTextureFromPostProcess('textureSampler', first);
  });
  adaptPass.onApplyObservable.add(() => {
    const e = now?.exposure;
    const auto = e?.mode === 'auto' ? e : { speed: 1, min: 1, max: 1 };
    adaptPass.effect.setTexture('meterSampler', meterTarget);
    adaptPass.effect.setTexture('previousSampler', levels[latest]!);
    adaptPass.effect.setFloat('dt', now?.dtS ?? 0);
    adaptPass.effect.setFloat('speed', auto.speed);
    adaptPass.effect.setFloat('lo', auto.min);
    adaptPass.effect.setFloat('hi', auto.max);
    adaptPass.effect.setFloat('reset', reset ? 1 : 0);
  });
  const measuring: Observer<Scene> = scene.onAfterRenderObservable.add(() => {
    if (!passes || now?.exposure?.mode !== 'auto') return;
    if (!meter.effect?.isReady() || !adaptPass.effect?.isReady()) return;
    renderer.render(meter, meterTarget);
    const next = 1 - latest;
    // Read from the level before, drawn into the other.
    renderer.render(adaptPass, levels[next]!);
    latest = next;
    reset = false;
  });

  return {
    update(frame) {
      const wasAuto = now?.exposure?.mode === 'auto';
      now = frame;
      const e = frame.exposure;
      if (e?.mode === 'auto' && !wasAuto) reset = true;
      const beams = opts.sunbeams && frame.sunbeams > 0;
      const view = beams || e?.mode === 'auto' || (e?.mode === 'fixed' && e.value !== 1);
      if (beams !== drawn.beams || view !== drawn.view) {
        removePasses();
        if (view) makePasses(beams);
        drawn = { beams, view };
      }
      if (!beams) return;
      // Where the sun is on the screen: its direction through the camera's view and projection, as a point at infinity.
      const m = camera.getTransformationMatrix().m;
      const s = frame.sun;
      const x = s.x * m[0]! + s.y * m[4]! + s.z * m[8]!;
      const y = s.x * m[1]! + s.y * m[5]! + s.z * m[9]!;
      const w = s.x * m[3]! + s.y * m[7]! + s.z * m[11]!;
      const inFront = w > 1e-6;
      const nx = inFront ? x / w : 0;
      const ny = inFront ? y / w : 0;
      sunUv = [nx * 0.5 + 0.5, ny * 0.5 + 0.5];
      beamsStrength = frame.sunbeams * sunbeamsByHeight(frame.sunHeight) * sunOnScreen(nx, ny, inFront);
    },
    dispose() {
      scene.onAfterRenderObservable.remove(measuring);
      removePasses();
      meter.dispose();
      adaptPass.dispose();
      renderer.dispose();
      meterTarget.dispose();
      for (const l of levels) l.dispose();
    },
  };
}
